			{ run: capital.shortBeamRight, likelihood: 1 },
			{ run: capital.beamLeft, likelihood: 1 },
			{ run: capital.shortBeamLeft, likelihood: 1 },
			{ run: capital.beam, likelihood: 1 },
			{ run: capital.shortBeam, likelihood: 1 },
