			{ run: lowercase.circle, likelihood: 1.5 },
			{ run: lowercase.stem, likelihood: 1 },
			{ run: lowercase.shortStem, likelihood: 0.25 },
			// { run: lowercase.fwdSlash, likelihood: 1 },
