		push()
		translate(0, -letterHeight/2)
		weightedRandom([
			{ run: lowercase.midBeam, likelihood: 1 },
			{ run: noop, likelihood: 1 },
		])
		pop()
	},
	shortStem: () => {
		line(0, 0, 0, -letterHeight/2)
		push()
		translate(0, -letterHeight/2)
		weightedRandom([
			{ run: lowercase.midBeam, likelihood: 1 },
			{ run: noop, likelihood: 1 },
		])
		pop()
