// === Tab: utils ===
function weightedRandom(values) {
	const options = values.map((v) => v.run)
	const weights = values.map((v) => v.likelihood)
  const sumWeights = weights.reduce((acc, next) => acc + next)
  let pickedWeight = random(sumWeights)
  for (let i = 0; i < weights.length; i++) {
    pickedWeight -= weights[i]
    if (pickedWeight <= 0) {
      return options[i]()
    }
  }
  return options[options.length - 1]()
}

function noop() {}

const letterWidth = 10
const letterHeight = 20

// === Tab: mySketch ===
function setup() {
	createCanvas(600, 600)
	pixelDensity(2)
}

function mousePressed() {
	saveCanvas('writing.png')
}

function draw() {
	if (frameCount % (2 * 60) === 1) {
		background(255)
		noFill()
		translate(letterWidth * 2, letterHeight * 1.75)

		for (let line = 0; line < 24; line++) {
			push()
			let isFirstLetter = true
			for (let char = 0; char < 48; char++) {
				if (isFirstLetter) {
					capital.root()
					isFirstLetter = false
				} else if (random() < 0.8) {
					lowercase.root()
				} else {
					isFirstLetter = true
				}
				translate(letterWidth * 1.2, 0)
			}
			pop()
			translate(0, letterHeight * 1.2)
		}
	}
}
